-- Seed Western Cape pharmacy directory from the WHF Pharmacy Network List, updated July 2024.
-- Generated by scripts/build-whf-directory.mjs. Safe to run more than once.

alter table public.pharmacy_directory add column if not exists source_page integer;
alter table public.pharmacy_directory add column if not exists validation_status text not null default 'needs_review';
alter table public.pharmacy_directory add column if not exists location_precision text not null default 'unknown';

create index if not exists pharmacy_directory_town_idx on public.pharmacy_directory(town) where active;
create index if not exists pharmacy_directory_suburb_idx on public.pharmacy_directory(suburb) where active;
create index if not exists pharmacy_directory_active_idx on public.pharmacy_directory(active, verification_status);
create index if not exists pharmacy_directory_address_trgm_idx on public.pharmacy_directory using gin (normalised_address gin_trgm_ops);


on conflict (source_record_hash) do update set
  practice_number = excluded.practice_number,
  practice_name = excluded.practice_name,
  normalised_name = excluded.normalised_name,
  town = excluded.town,
  suburb = excluded.suburb,
  city = excluded.city,
  province = excluded.province,
  physical_address = excluded.physical_address,
  normalised_address = excluded.normalised_address,
  telephone = excluded.telephone,
  latitude = coalesce(public.pharmacy_directory.latitude, excluded.latitude),
  longitude = coalesce(public.pharmacy_directory.longitude, excluded.longitude),
  location_quality = case when public.pharmacy_directory.latitude is not null and public.pharmacy_directory.longitude is not null then public.pharmacy_directory.location_quality else excluded.location_quality end,
  location_precision = case when public.pharmacy_directory.latitude is not null and public.pharmacy_directory.longitude is not null then public.pharmacy_directory.location_precision else excluded.location_precision end,
  geocode_source = case when public.pharmacy_directory.latitude is not null and public.pharmacy_directory.longitude is not null then public.pharmacy_directory.geocode_source else excluded.geocode_source end,
  geocode_status = case when public.pharmacy_directory.latitude is not null and public.pharmacy_directory.longitude is not null then public.pharmacy_directory.geocode_status else excluded.geocode_status end,
  source_name = excluded.source_name,
  source_updated_at = excluded.source_updated_at,
  source_page = excluded.source_page,
  verification_status = excluded.verification_status,
  validation_status = excluded.validation_status,
  active = excluded.active;


